import struct, json

data = open('/app/trunc.db','rb').read()

def varint(b, o):
    v = 0
    for i in range(9):
        x = b[o+i]
        if i == 8:
            v = (v << 8) | x
            return v, o+9
        v = (v << 7) | (x & 0x7f)
        if not (x & 0x80):
            return v, o+i+1

count, _ = varint(data, 1)
pointers = [struct.unpack('>H', data[10+2*i:12+2*i])[0] for i in range(count)]

out = []
for p in pointers:
    rid, o = varint(data, p)
    hl, o = varint(data, o)
    end = o + hl
    types = []
    while o < end:
        t, o = varint(data, o)
        types.append(t)
    vals = []
    for t in types:
        if t == 0: vals.append(None)
        elif t in (1,2,3,4,5,6,8): vals.append(int.from_bytes(data[o:o+1<<((t-1)//3)], 'big', signed=True))
        elif t == 9: vals.append(1)
        elif t == 10: vals.append(0)
        elif t >= 13 and t % 2: n=(t-13)//2; v=data[o:o+n].decode('utf-8','replace'); o+=n; vals.append(v)
        else: raise ValueError(t)
    out.append({'word': vals[0], 'value': vals[1]})

out.sort(key=lambda r: r['value'] if isinstance(r['value'], int) else 0)
json.dump(out, open('/app/recover.json','w'))
print(json.dumps(out))
